    topOperations: Array.from(toolStats.entries()).sort((a, b) => b[1].count - a[1].count).slice(0, 5).map(([op, stats]) => ({
      operation: op,
      count: stats.count,
      avgTime: stats.avgTime.toFixed(3) + "ms"
    }))
